mapper.select:
SELECT so.id, so.stocktake_no, so.warehouse_id, w.warehouse_name, so.stocktake_date, so.stocktake_scope, so.stocktake_mode, so.freeze_mode, so.blind_count, so.order_status, so.confirm_time, so.confirm_by, cu.nickname AS confirm_by_name, so.create_by, u.nickname AS create_by_name, so.create_time FROM wms_stocktake_order so LEFT JOIN wms_warehouse w ON so.warehouse_id = w.id LEFT JOIN sys_user u ON so.create_by = u.user_id LEFT JOIN sys_user cu ON so.confirm_by = cu.user_id
AND so.deleted = 0
AND so.stocktake_no LIKE CONCAT('%', #{qo.stocktakeNo}, '%')
AND so.warehouse_id = #{qo.warehouseId}
AND so.order_status = #{qo.orderStatus}
AND so.stocktake_date >= #{qo.stocktakeDateStart}
AND so.stocktake_date <= #{qo.stocktakeDateEnd}
ORDER BY so.create_time DESC

SELECT stocktake_order_id AS stocktakeOrderId, COUNT(*) AS skuCount, SUM(CASE WHEN diff_quantity IS NOT NULL AND diff_quantity != 0 THEN 1 ELSE 0 END) AS diffCount, SUM(CASE WHEN stocktake_status = 'COUNTED' THEN 1 ELSE 0 END) AS countedCount FROM wms_stocktake_order_item WHERE stocktake_order_id IN
#{id}
GROUP BY stocktake_order_id
